import {circuits171,drawing171} from './electrical171.js?v=174';
import {initial173,all173,fmt173,scope173,sources173,insulations173} from './cable173.js?v=174';
import {PDF173} from './pdf173.js?v=174';
export const escape173=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function drawing173(state=initial173()){
 const a=drawing171().map(o=>({...o})),T=(x,y,s,h=3)=>a.push({t:'T',x,y,s,h,l:'TEXTOS'}),L=(x,y,u,v)=>a.push({t:'L',x,y,u,v,l:'MARCO'});
 const replace=(old,s)=>{const o=a.find(o=>o.t==='T'&&o.s===old);if(o)o.s=s;};
 replace('SR-UN-001 · REV. 171 · UNIFILAR FUNCIONAL / CÉDULAS POR CIRCUITO','SR-UN-001 · REV. 173 · ESTIMACIÓN PARA SIMULACIÓN EDUCATIVA');
 replace('23 kV de referencia · fases / Hz pendientes',`${fmt173(state.C01.voltage/1000)} kV · ${state.C01.phases} fases · ${state.C01.hz} Hz [ref./sup.]`);
 replace('Secundarios / V·A / conexión: pendientes',`${fmt173(state.C03.voltage)} V · conexión / placa pendientes`);
 replace('BARRA + / 750 V de referencia',`BARRA + / ${fmt173(state.C04.voltage)} V [ref./sup.]`);
 replace('Q-AUX · calibre pendiente','Q-AUX · ver cédula C06');
 replace('BARRA AUX / tensión pendiente',`BARRA AUX / ${fmt173(state.C07.voltage)} V [sup.]`);
 // Keep the original circuit geometry uncluttered; a keyed annotation ledger shares the sheet.
 L(420,7,587,7);L(587,7,587,410);L(420,410,587,410);L(420,7,420,410);
 T(426,18,'CÉDULAS VINCULADAS / ESCENARIO EDITABLE',3.5);T(426,25,'Valores propuestos; [M] = hipótesis manual / verificar',3);
 all173(state).forEach((r,i)=>{const y=35+i*25;L(420,y-5,587,y-5);const s=r.input;T(426,y,`${r.id} · ${r.status.includes('manual')?'[M] ':''}${r.id==='PE01'?'PE según circuito':fmt173(s.voltage)+' V · '+fmt173(s.nominal)+' A nominal'}`);T(426,y+6,r.id==='PE01'?'Conductor al electrodo: pendiente (250-66)':`I diseño ${fmt173(r.design)} A · ${s.material} ${fmt173(r.section)} mm²`);T(426,y+12,r.id==='PE01'?'No enlazar con retorno de tracción':`OCP ${fmt173(r.ocp)} A · L ${s.length} m · caída ${fmt173(r.dropPct)} %`);T(426,y+18,r.id==='PE01'?'Ver requisitos particulares en cédulas':r.section?`PE Cu ${fmt173(r.pe?.[0])} mm² · ${s.raceway} ${fmt173(r.racewaySize)} mm`:'SIN SELECCIÓN / consultar alertas');});
 T(14,308,'BASES DEL CÁLCULO / SUPUESTOS',4);T(14,318,'Cada identificador Cxx abre sus entradas, resultados, fórmulas y advertencias. Sin placas verificadas.',3.2);
 T(14,327,'23 kV y 750 V son referencias originales del simulador; las demás entradas iniciales son supuestas.',3.2);
 T(14,336,'Circuitos independientes: las cargas NO se suman automáticamente ni sustituyen un estudio de demanda.',3.2);
 T(14,345,'Baja tensión: NOM-001-SEDE-2012, tabla 310-15(b)(16); terminales, temperatura y agrupamiento.',3.2);
 T(14,354,'Tracción exclusiva: evaluar exclusión 1.2.2(c). MT: ampacidad manual, NO tabla de baja tensión.',3.2);
 T(14,363,'Caída: aproximación R/X con longitud de ida. Objetivo 3 % por tramo y 5 % combinado, recomendación.',3.2);
 T(14,372,'Tubería: ocupación con diámetro exterior supuesto; verificar fabricante. Charola: caso multiconductor acotado / verificar marcado y cable.',3.2);
 T(14,381,'Motores, transformadores, incendio y control tienen condiciones particulares; ver memoria adjunta.',3.2);
 T(14,390,'Unidades: NOM-008-SE-2021. Símbolos: IEEE/ANSI 315; referencia gráfica, no ley de instalación.',3.2);
 T(14,402,'HOJA A2 · NEGRO / BLANCO · NO USAR PARA CONSTRUCCIÓN · Referencias y criterios disponibles sin conexión.',3.2);
 return a;
}
export function svg173(state){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 594 420" role="img" aria-label="Unifilar y cédulas calculadas"><style>line,circle{stroke:#000;stroke-width:.3;fill:none}text{fill:#000;stroke:none;font-family:Arial,sans-serif}[data-circuit171]{cursor:pointer}[aria-pressed=true] line{stroke-width:.7}</style><rect width="594" height="420" fill="#fff"/>${drawing173(state).map(o=>{let s=o.t==='L'?`<line x1="${o.x}" y1="${o.y}" x2="${o.u}" y2="${o.v}"/>`:o.t==='C'?`<circle cx="${o.x}" cy="${o.y}" r="${o.r}"/>`:`<text x="${o.x}" y="${o.y}" font-size="${o.h}">${escape173(o.s)}</text>`;return o.c?`<g data-circuit171="${o.c}" role="button" tabindex="0" aria-label="Editar circuito ${o.c}">${s}</g>`:s;}).join('')}</svg>`;}
export function pdf173(state){const p=new PDF173().diagram(drawing173(state));for(const r of all173(state)){p.report(`${r.id} / ${r.destination}`,[...r.rows,['Alcance',r.scope],['Procedencia','Sin placas verificadas. Tensiones 23 kV y 750 V: referencias del simulador en C01/C02/C04; resto de entradas iniciales supuestas.'],['Datos de entrada completos',JSON.stringify(r.input)],...(r.formulas||[]).map((v,i)=>['Fórmula '+(i+1),v]),...r.warnings.map(v=>['Advertencia',v]),...r.pending.map(v=>['Pendiente',v])]);}p.report('Referencias / uso del escenario',sources173.map(s=>[s[1],s[3]]).concat([['Criterios','Archivo local normativa/criterios173.html; tablas del PDF oficial NOM-001-SEDE-2012. Consulta 21 octubre 2026.'],['Simbología','IEEE/ANSI 315-1975 (Inactive-Reserved), funciones IEEE C37.2-2022; cotejo autorizado pendiente. NMX-J-136-ANCE-2019: referencia nacional. No confundir con requisitos NOM de instalación.'],['Limitaciones',scope173]]));return p.finish();}
export function save173(data,type,name){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([data],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000);}
const fields173=[
 ['nominal','Corriente nominal / A',.01,10000],['voltage','Tensión entre conductores / V',1,100000],['phases','Sistema',[['0','CD · dos polos'],['1','CA · fase + neutro'],['3','CA · tres fases']]],
 ['hz','Frecuencia CA / Hz',1,1000],['length','Longitud de ida / m',0,10000],['continuous','Carga continua / %',0,100],['material','Material',[['Cu','Cobre'],['Al','Aluminio']]],['insulation','Aislamiento',Object.keys(insulations173).map(k=>[k,k])],
 ['terminal','Terminal / °C',[['auto','Automática 60/75 (supuesto)'],['60','60'],['75','75 · marcado por verificar']]],['ambient','Ambiente / °C',-20,85],['group','Portadores totales agrupados',1,100],['neutral','Neutro trifásico',[['0','Sin neutro'],['1','Con neutro de sección completa']]],['neutralCounts','Neutro trifásico portador',[['1','Sí · armónicos / carga no lineal'],['0','Sólo desequilibrio · verificar']]],
 ['pf','Factor de potencia CA',.01,1],['conductorTemp','Temperatura para resistencia / °C',20,90],['x','Reactancia supuesta / ohm/km',0,2],['upstreamDrop','Caída aguas arriba / %',0,100],['dropLimit','Objetivo de caída del tramo / %',.1,10],
 ['raceway','Canalización',[['EMT','EMT · tabla 4'],['Tubería manual','Otra tubería · dimensiones manuales'],['Charola','Charola ventilada · cable multiconductor <4/0']]],['ductID','Otra tubería: diámetro interior / mm',1,1000],['ductArea','Otra tubería: área interior / mm²',1,1000000],['odExtra','Adición diametral al cable de fase / mm',0,50],['peODExtra','Adición diametral al PE Cu / mm',0,50],['trayCableOD','Charola: diámetro del multiconductor / mm',1,150],['trayOtherArea','Charola: área de otros cables <4/0 / mm²',0,50000],
 ['motorFLC','Motor: FLC de tabla supuesta / A',.01,1000],['motorPlate','Motor: corriente de placa supuesta / A',.01,1000],['serviceFactor','Motor: factor de servicio supuesto',1,2],['transformerCurrent','TA-1: corriente nominal de placa / A',.01,10000],
 ['manualSection','MT / retorno / incendio: sección equivalente / mm²',.01,507],['manualAmpacity','MT / especial: ampacidad manual / A',.01,10000],['manualFactor','MT / especial: factor global manual',.01,2],['manualOCP','MT / especial: protección manual / A',.01,10000]
];
export function mountInstallation173(overlay,onPart,onState){
 const fresh=initial173();let state=fresh;try{const saved=JSON.parse(localStorage.getItem('metro-installation173'));if(saved&&Object.keys(fresh).every(k=>saved[k]))state=Object.fromEntries(Object.keys(fresh).map(k=>[k,{...fresh[k],...saved[k],edited:{...saved[k].edited}}]));}catch{}let selected='C09';
 const tools=overlay.querySelector('.cad168-tools'),btn=document.createElement('button');btn.textContent='Calcular instalación / cédulas';btn.dataset.cadSchedules171='';tools.append(btn);
 const pdf=document.createElement('button');pdf.textContent='Descargar PDF · plano + cédulas';pdf.dataset.cadPdf173='';tools.append(pdf);
 const pane=document.createElement('aside');pane.className='schedule171 installation173';pane.hidden=true;pane.innerHTML=`<header><h3>Instalación educativa</h3><button data-schedule-close aria-label="Cerrar cédula">×</button></header><p>${scope173}</p><label>Circuito <select data-schedule-select>${circuits171.map(c=>`<option value="${c.id}">${c.id} · ${escape173(c.destination)}</option>`).join('')}</select></label><div data-install-inputs></div><p data-install-status role="status" aria-live="polite"></p><div data-schedule-data></div><button data-schedule-model>Ubicar equipo en 3D</button><button data-schedule-csv>Exportar resultados · CSV</button><button data-install-json>Guardar escenario · JSON</button><label>Recuperar escenario JSON <input type="file" accept=".json,application/json" data-install-import></label><button data-install-reset>Restablecer este circuito</button><p><a href="./normativa/criterios173.html" target="_blank">Fórmulas y referencias locales ↗</a> · <a href="./normativa/NOM-001-SEDE-2012.pdf.gz" target="_blank">NOM oficial en PDF ↗</a></p>`;overlay.querySelector('.cad168-body').append(pane);
 const origin=(key)=>state[selected].edited[key]?'Introducido por usuario · sin verificar':key==='voltage'&&['C01','C02','C04'].includes(selected)?'Referencia original del simulador · sin placa':'Supuesto educativo editable';
 function inputForm(){const s=state[selected],c=circuits171.find(c=>c.id===selected);pane.querySelector('[data-install-inputs]').innerHTML=selected==='PE01'?'<p>Consulta el PE propuesto en cada circuito. El conductor del electrodo no se dimensiona sin los datos del sistema.</p>':`<details open><summary>Datos y supuestos · ${selected}</summary><p>Los circuitos se calculan individualmente; no se suman cargas aguas arriba. Comprueba demanda, tensiones y relaciones de transformación.</p><div class="input-grid173">${fields173.filter(([k])=>k.startsWith('manual')?['MT','FIRE'].includes(c.criterion)||c.id==='C05':k.startsWith('motor')||k==='serviceFactor'?c.id==='C08':k==='transformerCurrent'?c.id==='C06':true).map(([k,label,min,max])=>`<label>${label}${Array.isArray(min)?`<select data-input173="${k}">${min.map(([v,l])=>`<option value="${v}"${String(s[k])===v?' selected':''}>${l}</option>`).join('')}</select>`:`<input data-input173="${k}" type="number" min="${min}" max="${max}" step="${['group','hz'].includes(k)?1:'any'}" value="${s[k]}">`}<small data-origin173="${k}">${origin(k)}</small></label>`).join('')}</div><label>Notas / datos pendientes propios<textarea data-input173="notes">${escape173(s.notes)}</textarea></label></details>`;}
 function result(){const c=circuits171.find(c=>c.id===selected),r=all173(state).find(r=>r.id===selected);pane.querySelector('[data-schedule-data]').innerHTML=`<h4>${r.id} · ${escape173(r.origin)} → ${escape173(r.destination)}</h4><p><b>${escape173(r.status)}</b></p><table><tbody>${r.rows.map(([k,v])=>`<tr><th scope="row">${escape173(k)}</th><td>${escape173(v)}</td></tr>`).join('')}</tbody></table><details open><summary>Advertencias y verificaciones pendientes</summary><ul>${r.warnings.concat(r.pending).map(v=>`<li>${escape173(v)}</li>`).join('')}</ul></details><details><summary>Memoria de cálculo / criterios</summary>${(r.formulas||[]).map(v=>`<p>${escape173(v)}</p>`).join('')}<p>${escape173(r.refs.join('; '))}</p><p>${escape173(c.scope)}</p></details>`;onState(state);try{localStorage.setItem('metro-installation173',JSON.stringify(state));pane.querySelector('[data-install-status]').textContent='Cálculo actualizado. Escenario guardado en este navegador.';}catch{pane.querySelector('[data-install-status]').textContent='Cálculo actualizado. Almacenamiento no disponible; exporta JSON para conservarlo.';}}
 function select(id){if(!state[id])return;selected=id;pane.hidden=false;btn.setAttribute('aria-expanded','true');pane.querySelector('[data-schedule-select]').value=id;inputForm();result();}
 pane.addEventListener('input',e=>{const k=e.target.dataset.input173;if(!k)return;if(e.target.type==='number'&&!e.target.validity.valid){pane.querySelector('[data-install-status]').textContent='Valor fuera de rango; se conserva el último cálculo válido.';return;}const val=e.target.value;if(k==='notes'||['material','insulation','terminal','raceway'].includes(k))state[selected][k]=val;else state[selected][k]=val===''?NaN:Number(val);state[selected].edited[k]=true;const badge=pane.querySelector(`[data-origin173="${k}"]`);if(badge)badge.textContent=origin(k);result();});
 btn.onclick=()=>pane.hidden?select(selected):(pane.hidden=true,btn.setAttribute('aria-expanded','false'));
 pane.querySelector('[data-schedule-close]').onclick=()=>{pane.hidden=true;btn.setAttribute('aria-expanded','false');};pane.querySelector('[data-schedule-select]').onchange=e=>select(e.target.value);
 const activate=e=>{const g=e.target.closest('[data-circuit171]');if(g){e.preventDefault();select(g.dataset.circuit171);}};overlay.addEventListener('click',activate);overlay.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key))activate(e);});
 pane.querySelector('[data-schedule-model]').onclick=()=>onPart(circuits171.find(c=>c.id===selected).part);
 pane.querySelector('[data-install-reset]').onclick=()=>{state[selected]=initial173()[selected];select(selected);};
 pane.querySelector('[data-install-json]').onclick=()=>save173(JSON.stringify({version:173,state},null,2),'application/json','MetroLab_Escenario_R173.json');
 pane.querySelector('[data-install-import]').onchange=async e=>{try{const data=JSON.parse(await e.target.files[0].text());if(data.version!==173||!Object.keys(fresh).every(k=>data.state?.[k]&&Object.keys(fresh[k]).every(f=>Object.hasOwn(data.state[k],f))))throw Error('Formato incompatible');const test=all173(data.state);if(test.some(r=>r.status==='Entrada inválida'||r.status==='Entrada manual inválida'))throw Error('Entradas inválidas');state=data.state;select(selected);}catch(err){pane.querySelector('[data-install-status]').textContent='No se pudo importar: '+err.message;}};
 pane.querySelector('[data-schedule-csv]').onclick=async()=>{const {csv173}=await import('./cable173.js?v=174');save173(csv173(all173(state)),'text/csv;charset=utf-8','MetroLab_Cedulas_R173.csv');};
 pdf.onclick=()=>{try{save173(pdf173(state),'application/pdf','MetroLab_Unifilar_Cedulas_R173.pdf');}catch(err){pane.querySelector('[data-install-status]').textContent='No se pudo exportar PDF: '+err.message;pane.hidden=false;}};
 onState(state);return {get state(){return state;},select};
}
